package cn.zhuatech.mcpgateway.controller; import cn.zhuatech.mcpgateway.common.ApiResponse; import cn.zhuatech.mcpgateway.dto.McpGatewayDto.*; import cn.zhuatech.mcpgateway.service.McpGatewayService; import cn.zhuatech.mcpgateway.service.McpAccessPolicyService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('DOMAIN_USER','ADMIN')") public class WorkspaceController {private final McpGatewayService service;private final McpAccessPolicyService policy;public WorkspaceController(McpGatewayService service,McpAccessPolicyService policy){this.service=service;this.policy=policy;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("网关处置反馈已提交",service.report(id,request));}@PostMapping("/access-decision") public ApiResponse<McpAccessPolicyService.Result> decide(@Valid @RequestBody McpAccessPolicyService.Request request){return ApiResponse.ok("访问策略判定完成",policy.decide(request));}}
